let payload;
try {
  const raw = $flow.state.payload;
  payload = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return JSON.stringify({ valid: false, problem_count: 1, problems: [{ path: '/', problem: 'payload is not valid JSON: ' + e.message }] });
